import type { Lang } from "@/lib/i18n";

export const hubDesc: Record<string, Record<Lang, string>> = {"manuale":{"it":"Leggete le regole della casa. Prima di usare qualcosa di cui non conoscete il funzionamento, consultate il manuale: contiene le spiegazioni delle dotazioni che non sono intuitive. Se non trovate un’istruzione o avete dubbi, scriveteci su WhatsApp.","en":"Please read the house rules. Before using anything unfamiliar, consult the manual: it explains equipment that is not intuitive. If an instruction is missing or you have questions, message us on WhatsApp.","es":"Leed las reglas de la casa. Antes de usar algo cuyo funcionamiento no conocéis, consultad el manual: explica los equipos que no son intuitivos. Si falta una instrucción o tenéis dudas, escribidnos por WhatsApp.","fr":"Lisez le règlement de la maison. Avant d’utiliser un équipement dont vous ne connaissez pas le fonctionnement, consultez le manuel : il explique les équipements moins intuitifs. S’il manque une instruction ou si vous avez un doute, écrivez-nous sur WhatsApp.","de":"Lest bitte die Hausregeln. Schaut vor der Nutzung unbekannter Geräte ins Handbuch: Es erklärt die weniger intuitiven Ausstattungen. Falls eine Anleitung fehlt oder ihr Fragen habt, schreibt uns auf WhatsApp."},"regole":{"it":"Per garantire un soggiorno piacevole a tutti e mantenere la casa nelle migliori condizioni, vi chiediamo di rispettare queste semplici regole.","en":"To ensure an enjoyable stay for everyone and keep the house in the best condition, please follow these simple rules.","es":"Para garantizar una estancia agradable para todos y mantener la casa en las mejores condiciones, respetad estas sencillas reglas.","fr":"Pour garantir un séjour agréable à tous et préserver la maison, merci de respecter ces règles simples.","de":"Damit alle einen angenehmen Aufenthalt haben und das Haus in bestem Zustand bleibt, bitten wir euch, diese einfachen Regeln zu beachten."},"luoghi":{"it":"Abbiamo diviso i luoghi per zona, così potete scegliere più facilmente cosa visitare in base al tempo che avete e a come volete organizzarvi.","en":"We have divided the places by area, so you can choose more easily what to visit depending on your time and plans.","es":"Hemos dividido los lugares por zona, para que podáis elegir más fácilmente qué visitar según el tiempo que tenéis y cómo queréis organizaros.","fr":"Nous avons divisé les lieux par zone, afin que vous puissiez choisir plus facilement quoi visiter selon le temps disponible et votre organisation.","de":"Wir haben die Orte nach Gebieten eingeteilt, damit ihr leichter entscheiden könnt, was ihr je nach Zeit und Planung besuchen möchtet."},"mangiare":{"it":"Scegli una categoria e scopri i nostri consigli da salernitani.","en":"Choose a category and discover our local recommendations.","es":"Elige una categoría y descubre nuestras recomendaciones locales.","fr":"Choisissez une catégorie et découvrez nos recommandations locales.","de":"Wählt eine Kategorie und entdeckt unsere Tipps aus Salerno."},"trasporti":{"it":"Da A Casa di Marco potete raggiungere il centro di Salerno, il lungomare, il porto e la Costiera Amalfitana usando bus, traghetti, taxi o auto.","en":"From A Casa di Marco you can reach Salerno city centre, the seafront, the port and the Amalfi Coast by bus, ferry, taxi or car.","es":"Desde A Casa di Marco podéis llegar al centro de Salerno, al paseo marítimo, al puerto y a la Costa Amalfitana en bus, ferry, taxi o coche.","fr":"Depuis A Casa di Marco, vous pouvez rejoindre le centre de Salerne, le front de mer, le port et la Côte Amalfitaine en bus, ferry, taxi ou voiture.","de":"Von A Casa di Marco aus erreicht ihr das Zentrum von Salerno, die Strandpromenade, den Hafen und die Amalfiküste mit dem Bus, der Fähre, dem Taxi oder dem Auto."},"spesa":{"it":"Qui trovate minimarket, supermercati e negozi utili vicino alla casa o comodi da raggiungere in auto.","en":"Here you will find minimarkets, supermarkets and useful shops near the house or easy to reach by car.","es":"Aquí encontraréis minimarkets, supermercados y tiendas útiles cerca de la casa o fáciles de alcanzar en coche.","fr":"Vous trouverez ici des supérettes, supermarchés et magasins utiles près de la maison ou faciles d'accès en voiture.","de":"Hier findet ihr Minimärkte, Supermärkte und nützliche Geschäfte in der Nähe des Hauses oder bequem mit dem Auto erreichbar."},"parcheggio":{"it":"Qui trovate le indicazioni per parcheggiare presso la struttura e alcune soluzioni consigliate per visitare Salerno.","en":"Here you will find parking instructions for the property and some recommended options for visiting Salerno.","es":"Aquí encontraréis indicaciones para aparcar en la estructura y algunas opciones recomendadas para visitar Salerno.","fr":"Vous trouverez ici les indications pour vous garer à la maison et quelques solutions conseillées pour visiter Salerne.","de":"Hier findet ihr Anweisungen zum Parken bei der Unterkunft und einige empfohlene Optionen für den Besuch von Salerno."},"itinerario":{"it":"Il generatore combina Salerno, Costiera Amalfitana, mare, cultura, natura e consigli food in base al vostro ritmo. È una proposta orientativa: controllate sempre orari, meteo, traffico e disponibilità prima di partire.","en":"The generator combines Salerno, the Amalfi Coast, sea, culture, nature and food tips according to your pace. It is a guideline proposal: always check times, weather, traffic and availability before you set off.","es":"El generador combina Salerno, la Costa Amalfitana, el mar, la cultura, la naturaleza y consejos food según vuestro ritmo. Es una propuesta orientativa: comprobad siempre horarios, tiempo, tráfico y disponibilidad antes de salir.","fr":"Le générateur combine Salerne, la côte amalfitaine, la mer, la culture, la nature et des conseils food selon votre rythme. C’est une proposition indicative : vérifiez toujours les horaires, la météo, le trafic et la disponibilité avant de partir.","de":"Der Generator kombiniert Salerno, die Amalfiküste, Meer, Kultur, Natur und Food-Tipps passend zu eurem Tempo. Es ist ein unverbindlicher Vorschlag: Prüft immer Zeiten, Wetter, Verkehr und Verfügbarkeit, bevor ihr losfahrt."},"colazione":{"it":"La colazione è servita presso Brignan Cafè, bar convenzionato con A Casa di Marco.","en":"Breakfast is served at Brignan Cafè, partner café of A Casa di Marco.","es":"El desayuno se sirve en Brignan Cafè, cafetería asociada con A Casa di Marco.","fr":"Le petit-déjeuner est servi au Brignan Cafè, café partenaire de A Casa di Marco.","de":"Das Frühstück wird im Brignan Cafè serviert, einem Partnercafé von A Casa di Marco."},"farmacie-emergenze":{"it":"In caso di emergenza, non aspettate: chiamate subito il numero adatto. Per dubbi non urgenti potete scriverci su WhatsApp.","en":"In an emergency, do not wait: call the correct number immediately. For non-urgent doubts, you can message us on WhatsApp.","es":"En caso de emergencia, no esperéis: llamad inmediatamente al número adecuado. Para dudas no urgentes, podéis escribirnos por WhatsApp.","fr":"En cas d’urgence, n’attendez pas : appelez immédiatement le bon numéro. Pour les questions non urgentes, vous pouvez nous écrire sur WhatsApp.","de":"Im Notfall zögert nicht: ruft sofort die passende Nummer an. Bei nicht dringenden Fragen könnt ihr uns per WhatsApp schreiben."}};
